namespace ghidra.app.plugin.processors.sleigh.symbol;

using static ghidra.pcode.utils.SlaFormat;

using ghidra.app.plugin.processors.sleigh;
using ghidra.program.model.pcode;
using ghidra.program.model.pcode;

/**
 * Base class for symbols in sleigh
 */
public abstract class Symbol {
	private string name;
	private int id;			// Unique id across all symbols
	private int scopeid;	// id of scope this symbol is in

	public string getName() {
		return name;
	}

	public int getId() {
		return id;
	}

	public int getScopeId() {
		return scopeid;
	}

	public void decodeHeader(Decoder decoder)
    {
		int el = decoder.openElement();
		name = decoder.readString(ATTRIB_NAME);
		id = (int) decoder.readUnsignedInteger(ATTRIB_ID);
		scopeid = (int) decoder.readUnsignedInteger(ATTRIB_SCOPE);
		decoder.closeElement(el);
	}

	public abstract void decode(Decoder decoder, SleighLanguage sleigh);
}
